sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }


    if (newValue == 'Response Un-Successful - Error') {
        g_form.addErrorMessage('Holdings Data sync was not completed due to technical error. Please check the holdings manually. The technical issue has been reported to HSBC technical team.');
    } else if (newValue == 'Response Un-Successful-400 Client Error') { //7426
        g_form.addErrorMessage('Holdings Data sync was not completed due to token issue. Please contact the IT team for further assistance.');
    } else if (newValue == 'Response Un-Successful-500 Server Error') {
        g_form.addErrorMessage('Holdings Data sync was not completed due to upstream issue.  Please contact the IT team for further assistance.');
    } else {
        g_form.clearMessages();
        // g_form.addInfoMessage('<div class="row"><div class="" style="text-align: left;"><p style="white-space:pre;">Last Updated of Trade Data -  <b>' + g_form.getValue('sys_updated_on') + '</b>          Time of last refresh of on-demand data -  <b>' + g_form.getValue('last_refresh_date') + '</b>          Time of the last refresh of holdings data  -  <b>' + g_form.getValue('last_positions_refresh_date_time') + ' </b>          Time of last refresh of SWIFT data -  <b>' + g_form.getValue('last_swift_refresh_date_time') + '</b></p > </div></div > ');
        g_form.addInfoMessage('Last Updated of Trade Data -  <b>' + g_form.getValue('sys_updated_on') + '</b>          Time of last refresh of on-demand data -  <b>' + g_form.getValue('last_refresh_date') + '</b>          Time of the last refresh of holdings data  -  <b>' + g_form.getValue('last_positions_refresh_date_time') + ' </b>          Time of last refresh of SWIFT data -  <b>' + g_form.getValue('last_swift_refresh_date_time') + '</b>');

    }

}
